const PANE_WIDTH_MIN: f32 = 280.;
/// 顶栏图标按钮的统一尺寸/字号（左右箭头、+、下拉、文件、设置、窗口按钮都一样）
const HEAD_BTN: f32 = 24.;
const HEAD_GLYPH: f32 = 13.;

const PANE_WIDTH_MAX: f32 = 900.;
