/// 分割方向：Row = 左右并排；Col = 上下堆叠。
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SplitDir {
    Row,
    Col,
}

/// tab 宽度：按标题文字估宽（CJK 按双宽算），夹在 56..220 之间。
fn est_tab_width(title: &str) -> f32 {
    let mut w: f32 = 0.;
    for ch in title.chars() {
        w += if (ch as u32) > 0x2000 { 11.5f32 } else { 6.4f32 };
    }
    (w + 34.).clamp(56., 220.)
}

fn next_split_id() -> u64 {
    use std::sync::atomic::{AtomicU64, Ordering};
    static N: AtomicU64 = AtomicU64::new(1);
    N.fetch_add(1, Ordering::Relaxed)
}

/// 一个 tab 的 panel 布局树。Leaf(0) 固定是 chat panel。
#[derive(Clone, Debug)]
enum Layout {
    Leaf(u64),
    Split {
        id: u64,
        dir: SplitDir,
        /// 每个孩子的权重（和为 1 左右）
        sizes: Vec<f32>,
        children: Vec<Layout>,
    },
}

impl SplitDir {
    fn pane_kind(self) -> BlockPlacement {
        match self {
            SplitDir::Row => BlockPlacement::Right,
            SplitDir::Col => BlockPlacement::Bottom,
        }
    }
}

impl Layout {
    fn label(&self) -> String {
        match self {
            Layout::Leaf(id) => format!("leaf {id}"),
            Layout::Split { dir, children, .. } => {
                format!("{:?}({})", dir, children.len())
            }
        }
    }

    /// 把某个 leaf 一分为二：原 leaf 在前，新 leaf 在后。
    fn split(&mut self, leaf: u64, dir: SplitDir, new_leaf: u64) -> bool {
        match self {
            Layout::Leaf(id) if *id == leaf => {
                let old = *id;
                *self = Layout::Split {
                    id: next_split_id(),
                    dir,
                    sizes: if dir == SplitDir::Row {
                        vec![0.62, 0.38]
                    } else {
                        vec![0.6, 0.4]
                    },
                    children: vec![Layout::Leaf(old), Layout::Leaf(new_leaf)],
                };
                true
            }
            Layout::Split { children, .. } => {
                children.iter_mut().any(|child| child.split(leaf, dir, new_leaf))
            }
            _ => false,
        }
    }

    /// 摘掉一个 leaf；父 split 只剩一个孩子时折叠成那个孩子。
    fn remove(&mut self, leaf: u64) -> bool {
        if let Layout::Split { children, sizes, .. } = self {
            for index in 0..children.len() {
                if matches!(children[index], Layout::Leaf(id) if id == leaf) {
                    children.remove(index);
                    if index < sizes.len() {
                        sizes.remove(index);
                    }
                    let total: f32 = sizes.iter().sum();
                    if total > 0.0 {
                        for size in sizes.iter_mut() {
                            *size /= total;
                        }
                    }
                    if children.len() == 1 {
                        if let Some(only) = children.pop() {
                            *self = only;
                        }
                    }
                    return true;
                }
            }
            children.iter_mut().any(|child| child.remove(leaf))
        } else {
            false
        }
    }

    fn leaves(&self, out: &mut Vec<u64>) {
        match self {
            Layout::Leaf(id) => out.push(*id),
            Layout::Split { children, .. } => {
                for child in children {
                    child.leaves(out);
                }
            }
        }
    }

    /// 在同一个 split 里和相邻兄弟换位置（拖 header 用）。
    fn swap_neighbor(&mut self, leaf: u64, dir: SplitDir, delta: isize) -> bool {
        if let Layout::Split {
            dir: split_dir,
            sizes,
            children,
            ..
        } = self
        {
            if *split_dir == dir {
                if let Some(index) = children
                    .iter()
                    .position(|child| matches!(child, Layout::Leaf(id) if *id == leaf))
                {
                    let target = index as isize + delta;
                    if target >= 0 && (target as usize) < children.len() {
                        children.swap(index, target as usize);
                        if index < sizes.len() && (target as usize) < sizes.len() {
                            sizes.swap(index, target as usize);
                        }
                        return true;
                    }
                }
            }
            return children
                .iter_mut()
                .any(|child| child.swap_neighbor(leaf, dir, delta));
        }
        false
    }

    /// 在右侧编辑器列追加一个 leaf：根是 Row 且第一个孩子是 chat(Leaf(0)) 时均分右列。
    fn add_right(&mut self, leaf: u64) {
        const EDITOR_AREA: f32 = 0.40;
        if let Layout::Split {
            dir: SplitDir::Row,
            children,
            sizes,
            ..
        } = self
        {
            if matches!(children.first(), Some(Layout::Leaf(0))) {
                children.push(Layout::Leaf(leaf));
                let rest = (children.len() - 1) as f32;
                sizes.clear();
                sizes.push(1.0 - EDITOR_AREA);
                for _ in 0..(children.len() - 1) {
                    sizes.push(EDITOR_AREA / rest);
                }
                return;
            }
        }
        self.split(0, SplitDir::Row, leaf);
    }

    fn has(&self, leaf: u64) -> bool {
        match self {
            Layout::Leaf(id) => *id == leaf,
            Layout::Split { children, .. } => children.iter().any(|child| child.has(leaf)),
        }
    }

    fn set_sizes(&mut self, split_id: u64, sizes: Vec<f32>) {
        if let Layout::Split { id, sizes: cur, children, .. } = self {
            if *id == split_id {
                if sizes.len() == cur.len() {
                    *cur = sizes;
                }
                return;
            }
            for child in children.iter_mut() {
                child.set_sizes(split_id, sizes.clone());
            }
        }
    }

    /// 协议方向上的邻居 pane。`delta` 为 +1（right/down）或 -1（left/up）。
    fn neighbor(&self, leaf: u64, want: SplitDir, delta: isize) -> Option<u64> {
        let Layout::Split { dir, children, .. } = self else {
            return None;
        };
        if *dir == want {
            if let Some(index) = children.iter().position(|child| child.has(leaf)) {
                let target = index as isize + delta;
                if target >= 0 && (target as usize) < children.len() {
                    let mut leaves = Vec::new();
                    children[target as usize].leaves(&mut leaves);
                    return if delta > 0 {
                        leaves.first().copied()
                    } else {
                        leaves.last().copied()
                    };
                }
            }
        }
        children
            .iter()
            .find_map(|child| child.neighbor(leaf, want, delta))
    }

    /// 新建的那个二分里，把 `leaf` 的权重设成 `weight`（另一半补齐）。
    fn set_leaf_weight(&mut self, leaf: u64, weight: f32) -> bool {
        if let Layout::Split { children, sizes, .. } = self {
            if children.len() == 2 && sizes.len() == 2 {
                if let Some(index) = children
                    .iter()
                    .position(|child| matches!(child, Layout::Leaf(id) if *id == leaf))
                {
                    let weight = weight.clamp(0.15, 0.85);
                    sizes[index] = weight;
                    sizes[1 - index] = 1.0 - weight;
                    return true;
                }
            }
            return children
                .iter_mut()
                .any(|child| child.set_leaf_weight(leaf, weight));
        }
        false
    }

    fn sizes_of(&self, split_id: u64) -> Option<Vec<f32>> {
        match self {
            Layout::Leaf(_) => None,
            Layout::Split { id, sizes, children, .. } => {
                if *id == split_id {
                    return Some(sizes.clone());
                }
                children.iter().find_map(|child| child.sizes_of(split_id))
            }
        }
    }
}

/// 一个 tab：装若干 panel（panel1-omp / panel2-terminal …），同一时刻显示一个。
#[derive(Clone, Debug)]
struct Panel {
    id: String,
    /// 稳定编号（不随位置变化）：默认名字就是 "tab {number}"
    number: u32,
    /// 被最大化的 panel（只显示它）
    maximized: Option<u64>,
    /// 用户可改的名字；空 = 用当前 panel 的标题
    name: String,
    /// panel id（= dsh session id；terminal panel 也是 session id）
    blocks: Vec<String>,
    active: Option<String>,
    /// panel 布局树（Leaf(0) = chat）
    layout: Layout,
    /// 从磁盘读出来的原始布局，等 Root 建好再 materialize
    pending_layout: Option<Value>,
}

impl Panel {
    fn new(id: String, number: u32) -> Self {
        Self {
            id,
            number,
            maximized: None,
            name: String::new(),
            blocks: Vec::new(),
            active: None,
            layout: Layout::Leaf(0),
            pending_layout: None,
        }
    }

    fn label(&self, panel_title: impl Fn(&str) -> String) -> String {
        if !self.name.trim().is_empty() {
            return self.name.clone();
        }
        self.active
            .as_deref()
            .or_else(|| self.blocks.first().map(|s| s.as_str()))
            .map(|id| panel_title(id))
            .unwrap_or_else(|| "tab".to_string())
    }
}

#[derive(Clone, Debug)]
struct Space {
    id: String,
    name: String,
    cwd: String,
    panels: Vec<Panel>,
    active_panel: Option<String>,
}

impl Space {
    /// 这个 panel 在哪个 tab 里。
    fn tab_of(&self, panel: &str) -> Option<&Panel> {
        self.panels
            .iter()
            .find(|tab| tab.blocks.iter().any(|p| p == panel))
    }

    /// 当前 tab。
    fn current_tab(&self) -> Option<&Panel> {
        self.active_panel
            .as_deref()
            .and_then(|id| self.panels.iter().find(|tab| tab.id == id))
            .or_else(|| self.panels.first())
    }

    /// 把一个 panel 放进它应该在的 tab；没有就新建一个 tab。
    fn attach_panel(&mut self, panel: &str) {
        if self.tab_of(panel).is_some() {
            return;
        }
        let id = next_tab_id();
        let number = self.panels.iter().map(|tab| tab.number).max().unwrap_or(0) + 1;
        let mut tab = Panel::new(id.clone(), number);
        tab.blocks.push(panel.to_string());
        tab.active = Some(panel.to_string());
        self.panels.push(tab);
        self.active_panel = Some(id);
    }

    /// 把 panel 所在 tab 置为当前，并让该 tab 显示这个 panel。
    fn activate_panel(&mut self, panel: &str) {
        let tab_id = self.tab_of(panel).map(|tab| tab.id.clone());
        if let Some(tab_id) = tab_id {
            self.active_panel = Some(tab_id.clone());
            if let Some(tab) = self.panels.iter_mut().find(|tab| tab.id == tab_id) {
                tab.active = Some(panel.to_string());
            }
        }
    }

    fn all_panels(&self) -> Vec<String> {
        self.panels
            .iter()
            .flat_map(|tab| tab.blocks.iter().cloned())
            .collect()
    }
}


enum TerminalUp {
    Write(String),
    Resize(u16, u16),
}

async fn rows_first_session(rpc: &Rpc<'_>) -> Option<String> {
    let list = rpc
        .call("session/list", json!({ "_request": {} }))
        .await
        .ok()?;
    list.get("items")
        .and_then(|v| v.as_array())
        .and_then(|a| a.first())
        .and_then(|i| i.get("sessionId"))
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
}

enum Cmd {
    Refresh,
    ModelCatalog,
    SelectModel { provider: String, model: String },
    Follow(String),
    /// Start a background follow without changing the focused session.
    Watch(String),
    CancelSession(String),
    NewSession { cwd: Option<String> },
    /// 为一个 pane 建终端（会话 + terminal/create）
    NewTerminal {
        pane_id: u64,
        kind: BlockPlacement,
        cwd: Option<String>,
        /// 终端起来后自动敲进去的命令（例如 `npx -y @deepseek-harness-tui/dsh-tui`）
        run: Option<String>,
    },
    AttachTerminal {
        pane_id: u64,
        session_id: String,
        term_id: String,
    },
    Prompt { session_id: String, text: String, request_id: String, extra: Vec<Value> },
    /// 附件 staging：把字节交给 fileUploads/upload 换 receipt
    UploadFile {
        attach_id: u64,
        agent_id: String,
        name: String,
        data: Arc<Vec<u8>>,
    },
    TerminalInput { term_id: String, data: String },
    /// 订阅某个 session 的后台任务清单（job/list 是流）
    JobsWatch { session_id: Option<String> },
    /// 杀掉一个后台任务
    JobKill { session_id: String, job_id: String },
    /// 通用 RPC 透传：endpoint 是 dsh 的 api 名（"settings/describe" 等）
    Call {
        tag: String,
        endpoint: String,
        args: Value,
    },
    /// Fork 一个会话（atSeq = None 取最近完成的 turn；Some 到那条消息为止）
    ForkSession { session_id: String, at_seq: Option<u64> },
    /// 安装一个插件包（独立任务跑，取消不会被排队堵住）
    InstallPlugin {
        name: String,
        spec: String,
        registry: Option<String>,
        request_id: String,
        /// 批准构建脚本后重试时带上
        approved_builds: Option<Vec<String>>,
    },
    /// 取消一个进行中的安装
    CancelInstall { request_id: String },
    /// 打开系统文件选择框（zenity/kdialog），结果走 Ev::FilesPicked
    PickFiles,
    Cancel,
    Decide { event_id: String, allow: bool },
    AnswerQuestion { event_id: String, answer: Value },
    UpdateDsh,
}

/// 每个 shell 起来时写进环境，terminal-browser 靠它找到 omd 的 socket。
#[cfg(unix)]
fn terminal_browser_prelude() -> String {
    let path = block_socket_path()
        .display()
        .to_string()
        .replace('\'', "'\\''");
    format!("export TERMINAL_BROWSER_TERMINAL_SOCKET='{path}'\r")
}

/// The control socket is a Unix-domain socket; Windows has no equivalent
/// wired up yet, so terminal blocks start without the browser bridge.
#[cfg(not(unix))]
fn terminal_browser_prelude() -> String {
    String::new()
}

/// 终端 pane 没带 cwd 时的默认目录。
fn default_terminal_cwd() -> String {
    if cfg!(windows) {
        std::env::var("USERPROFILE").unwrap_or_else(|_| "C:\\".to_string())
    } else {
        "/tmp".to_string()
    }
}

fn shell_join(args: &[String]) -> String {
    args.iter()
        .map(|arg| {
            if arg
                .chars()
                .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.' | '/' | ':' | '@' | '='))
            {
                arg.clone()
            } else {
                format!("'{}'", arg.replace('\'', "'\\''"))
            }
        })
        .collect::<Vec<_>>()
        .join(" ")
}

/// terminal-browser unix socket 上的一次调用。
enum TbCall {
    Current { tty: Option<String>, cwd: Option<String> },
    List,
    Neighbor { pane: String, direction: String },
    Split {
        from: String,
        direction: String,
        command: Vec<String>,
        size: Option<f32>,
    },
    Send { pane: String, text: String },
    Paste { pane: String },
    Focus { pane: String },
}

enum Ev {
    HostReady(String),
    DshSessions(Vec<SessionRow>),
    ModelCatalog(Value),
    ModelSelected { provider: String, model: String },
    FollowStart(String),
    Event { session_id: String, value: Value },
    Line(String),
    StreamStart { session_id: String },
    StreamDelta { session_id: String, delta: String },
    ReasoningDelta { session_id: String, delta: String },
    StreamEnd { session_id: String },
    Connection(bool),
    AgentRunning(bool),
    ImageB64(String),
    TerminalOutput { term_id: String, data: String },
    TerminalScreen(Vec<String>),
    /// 新会话建好了：UI 把它加进当前空间的 tabs 并切过去
    SessionCreated(String),
    /// 终端建好了：把 term 绑到 pane 上（tab 形态的 pane 还会被打开成标签页）
    /// job/list 的一帧（整份清单替换）
    Jobs(Value),
    /// workspace/follow 的一帧（baseline / pinned / archived / …）
    Workspace(Value),
    /// session/control 的一个会话投影更新（title / permissions / inbox / …）
    ControlProjection {
        session_id: String,
        values: Value,
    },
    /// api-session/status emit：会话 running 翻转（args: [sessionId, running]）
    SessionStatus {
        session_id: String,
        running: bool,
    },
    Called {
        tag: String,
        endpoint: String,
        result: std::result::Result<Value, String>,
    },
    /// terminal-browser 的 socket 请求。UI 线程填 result，控制线程在等。
    Tb {
        call: TbCall,
        reply: tokio::sync::oneshot::Sender<Value>,
    },
    TerminalSession {
        pane_id: u64,
        kind: BlockPlacement,
        session_id: String,
        term_id: String,
    },
    /// NewTerminal 在 pane 落地前失败了：把已经写进布局的叶子摘掉，
    /// 否则那个 block 会永远停在 "starting…"。
    PaneAbandoned(u64),
    Approval { event_id: String, label: String },
    ApprovalGone,
    Question { event_id: String, request: Value },
    QuestionGone,
    /// 一个插件安装结束（成功/失败/取消/需要批准构建脚本）
    InstallSettled {
        name: String,
        result: std::result::Result<Value, String>,
    },
    /// 附件 staging 结束
    FileStaged {
        attach_id: u64,
        result: std::result::Result<Value, String>,
    },
    /// 文件选择框返回的路径
    FilesPicked(Vec<String>),
    DshInfo { version: String, bundled: bool },
    DshUpdate { done: bool, message: String },
    Error(String),
}

// ---------------------------------------------------------------------------
// worker：持有 host / rpc / mux，串行处理命令与流帧
// ---------------------------------------------------------------------------

/// 事件名（启动耗时日志用）。
fn ev_name(ev: &Ev) -> &'static str {
    match ev {
        Ev::HostReady(_) => "HostReady",
        Ev::DshSessions(_) => "DshSessions",
        Ev::ModelCatalog(_) => "ModelCatalog",
        Ev::ModelSelected { .. } => "ModelSelected",
        Ev::FollowStart(_) => "FollowStart",
        Ev::Event { .. } => "Event",
        Ev::Line(_) => "Line",
        Ev::StreamStart { .. } => "StreamStart",
        Ev::StreamDelta { .. } => "StreamDelta",
        Ev::ReasoningDelta { .. } => "ReasoningDelta",
        Ev::StreamEnd { .. } => "StreamEnd",
        Ev::Connection(_) => "Connection",
        Ev::AgentRunning(_) => "AgentRunning",
        Ev::ImageB64(_) => "ImageB64",
        Ev::SessionCreated(_) => "SessionCreated",
        Ev::TerminalOutput { .. } => "TerminalOutput",
        Ev::TerminalScreen(_) => "TerminalScreen",
        Ev::Jobs(_) => "Jobs",
        Ev::Called { .. } => "Called",
        Ev::TerminalSession { .. } => "TerminalSession",
        Ev::PaneAbandoned(_) => "PaneAbandoned",
        Ev::Tb { .. } => "Tb",
        Ev::Approval { .. } => "Approval",
        Ev::ApprovalGone => "ApprovalGone",
        Ev::Question { .. } => "Question",
        Ev::QuestionGone => "QuestionGone",
        Ev::InstallSettled { .. } => "InstallSettled",
        Ev::Workspace(_) => "Workspace",
        Ev::ControlProjection { .. } => "ControlProjection",
        Ev::SessionStatus { .. } => "SessionStatus",
        Ev::FileStaged { .. } => "FileStaged",
        Ev::FilesPicked(_) => "FilesPicked",
        Ev::DshInfo { .. } => "DshInfo",
        Ev::DshUpdate { .. } => "DshUpdate",
        Ev::Error(_) => "Error",
    }
}

fn spawn_worker(cmds: Receiver<Cmd>, evs: Sender<Ev>) {    eprintln!("[worker] thread starting");
    std::thread::spawn(move || {
        eprintln!("[worker] thread running");
        let rt = match tokio::runtime::Builder::new_multi_thread()
            .enable_all()
            .build()
        {
            Ok(rt) => rt,
            Err(err) => {
                let _ = evs.send_blocking(Ev::Error(format!("tokio: {err}")));
                return;
            }
        };
        rt.block_on(worker_main(cmds, evs));
    });
}

async fn worker_main(cmds: Receiver<Cmd>, evs: Sender<Ev>) {
    let worker_started = std::time::Instant::now();
    // First run on a clean machine: install the engine into the app directory,
    // mirroring Tern's `share/tern/omp` layout. A system `dsh` is only a
    // development fallback.
    if DshRuntime::current().is_none()
        && std::env::var("DSH_BIN").is_err()
        && std::env::var("DSH_GUI_NO_AUTO_INSTALL").is_err()
    {
        let _ = evs
            .send(Ev::DshUpdate {
                done: false,
                message: "installing bundled dsh engine…".into(),
            })
            .await;
        match dsh_host::install_dsh("latest").await {
            Ok(runtime) => {
                let _ = evs
                    .send(Ev::DshUpdate {
                        done: true,
                        message: format!("bundled engine v{} installed", runtime.version),
                    })
                    .await;
            }
            Err(err) => {
                let _ = evs
                    .send(Ev::DshUpdate {
                        done: true,
                        message: format!("bundled engine install failed: {err}"),
                    })
                    .await;
            }
        }
    }
    if let Some(rows) = load_sessions_cache() {
        eprintln!("[worker] cached sessions: {}", rows.len());
        stamp(format!("worker: session cache sent ({} rows)", rows.len()));
        let _ = evs.send(Ev::DshSessions(rows)).await;
    }
    eprintln!("[worker] launching host");
    stamp("worker: launching host");
    let host = match DshHost::launch("web").await {
        Ok(host) => host,
        Err(err) => {
            let _ = evs.send(Ev::Error(format!("host launch failed: {err}"))).await;
            return;
        }
    };
    stamp("worker: host attached");
    eprintln!(
        "[worker] host ready: {} ({}ms)",
        host.base(),
        worker_started.elapsed().as_millis()
    );
    let _ = evs.send(Ev::HostReady(host.base().to_string())).await;

    let rpc = Rpc::new(host.client(), host.base());
    let auth_client = host.client().clone();
    let auth_jar = host.jar();
    let auth_url = host.tokenized_url().clone();
    let cookie_provider: CookieProvider = Arc::new(move || {
        let client = auth_client.clone();
        let jar = auth_jar.clone();
        let url = auth_url.clone();
        Box::pin(async move { DshHost::auth_cookie(&client, &jar, &url).await })
    });
    let mux = match Mux::connect_with_provider(
        &host.ws_url("api/remote.mux").unwrap_or_default(),
        cookie_provider,
    )
    .await
    {
        Ok(mux) => mux,
        Err(err) => {
            let _ = evs.send(Ev::Error(format!("ws connect failed: {err}"))).await;
            return;
        }
    };

    // 连接状态：generation 出现即 connected，消失即 reconnecting。
    {
        let mut generations = mux.generations();
        let evs_status = evs.clone();
        tokio::spawn(async move {
            loop {
                let up = { generations.borrow().is_some() };
                let _ = evs_status.send(Ev::Connection(up)).await;
                if generations.changed().await.is_err() {
                    break;
                }
            }
        });
    }

    // 测试钩子：N 秒后主动断开 WebSocket，验证重连 + snapshot resync。
    if let Ok(secs) = std::env::var("DSH_GUI_RECONNECT_AFTER") {
        if let Ok(secs) = secs.parse::<u64>() {
            let mux = mux.clone();
            tokio::spawn(async move {
                tokio::time::sleep(std::time::Duration::from_secs(secs)).await;
                eprintln!("[worker] forcing reconnect");
                mux.force_reconnect();
            });
        }
    }

    // 流帧转发：Follow 时起一个 generation，旧帧直接丢弃。
    let (frame_tx, frame_rx) = async_channel::unbounded::<(String, Value)>();
    let generation = Arc::new(AtomicU64::new(0));
    let mut current: Option<String> = None;
    let mut followed: std::collections::HashSet<String> = std::collections::HashSet::new();
    let mut prompt_started: Option<std::time::Instant> = None;
    // 每次 Follow/NewSession 提升世代；旧 follow task 看到变化后主动取消流。
    let (follow_gen_tx, follow_gen_rx) = tokio::sync::watch::channel(0u64);
    // 本地回显过的 prompt rpcId；follow 回放同一条 user/message 时用它去重。
    let mut pending_echoes: VecDeque<String> = VecDeque::new();
    // 后台任务订阅的世代（换了 session 就作废旧流）
    let jobs_gen = std::sync::Arc::new(std::sync::atomic::AtomicU64::new(0));
    // 工具耗时：在这里打点（UI 侧事件是批量的，量出来恒为 0）
    let mut tool_started: std::collections::HashMap<String, std::time::Instant> =
        std::collections::HashMap::new();

    // 终端：每个终端一条 attach 流 + 自己的 uplink（支持多个 pane）
    let terminal_up: std::sync::Arc<
        tokio::sync::Mutex<
            std::collections::HashMap<String, tokio::sync::mpsc::UnboundedSender<TerminalUp>>,
        >,
    > = std::sync::Arc::new(tokio::sync::Mutex::new(std::collections::HashMap::new()));
    let terminal_buffers: Arc<tokio::sync::Mutex<std::collections::HashMap<String, String>>> =
        Arc::new(tokio::sync::Mutex::new(std::collections::HashMap::new()));
    #[cfg(unix)]
    {
        let control_path = block_socket_path();
        let http_c = host.client().clone();
        let base_c = host.base().clone();
        let mux_c = mux.clone();
        let evs_c = evs.clone();
        let up_c = terminal_up.clone();
        let buf_c = terminal_buffers.clone();
        tokio::spawn(async move {
            serve_control(control_path, http_c, base_c, mux_c, evs_c, up_c, buf_c).await;
        });
    }

    // 常驻订阅全局事件（审批/提问都走这里）
    {
        let evs = evs.clone();
        let mux_events = mux.clone();
        let http = host.client().clone();
        let base = host.base().clone();
        tokio::spawn(async move {
            let result_rpc = Rpc::new(&http, &base);
            let Some(mut events) = mux_events.take_events() else {
                return;
            };
            while let Some(value) = events.recv().await {
                match value.get("type").and_then(|v| v.as_str()) {
                    Some("emit") => {
                        let event = value.get("event").and_then(|v| v.as_str()).unwrap_or("");
                        eprintln!("[worker] emit: {event}");
                        if event == "approval/request" {
                            eprintln!("[worker] approval event: {}", value.to_string().chars().take(600).collect::<String>());
                            let event_id = value
                                .get("eventId")
                                .and_then(|v| v.as_str())
                                .unwrap_or("")
                                .to_string();
                            let label = value
                                .get("args")
                                .map(|a| a.to_string().chars().take(220).collect::<String>())
                                .unwrap_or_default();
                            let _ = evs.send(Ev::Approval { event_id, label }).await;
                        }
                        // 会话运行态（args: [sessionId, running]）——tab 上的活动点
                        if event == "api-session/status" {
                            let args = value.get("args").and_then(|a| a.as_array());
                            let session_id = args
                                .and_then(|a| a.first())
                                .and_then(|v| v.as_str())
                                .unwrap_or("")
                                .to_string();
                            let running = args
                                .and_then(|a| a.get(1))
                                .and_then(|v| v.as_bool())
                                .unwrap_or(false);
                            if !session_id.is_empty() {
                                let _ = evs
                                    .send(Ev::SessionStatus {
                                        session_id,
                                        running,
                                    })
                                    .await;
                            }
                        }
                    }
                    Some("waterfall") => {
                        let event = value.get("event").and_then(|v| v.as_str()).unwrap_or("");
                        let event_id = value
                            .get("eventId")
                            .and_then(|v| v.as_str())
                            .unwrap_or("")
                            .to_string();
                        if event == "approval/request" {
                            let req = value.get("request").cloned().unwrap_or(Value::Null);
                            let tool = req
                                .get("toolName")
                                .and_then(|v| v.as_str())
                                .unwrap_or("tool");
                            let reason = req
                                .get("reason")
                                .and_then(|v| v.as_str())
                                .unwrap_or("");
                            let label = format!("{tool}：{reason}");
                            eprintln!("[worker] approval waterfall {event_id}");
                            let _ = evs
                                .send(Ev::Approval {
                                    event_id: event_id.clone(),
                                    label,
                                })
                                .await;

                            // 调试钩子：自动放行/Deny，用于端到端验证
                            if let Ok(decision) = std::env::var("DSH_GUI_AUTODECIDE") {
                                let value = if decision == "allow" {
                                    "allowed-once"
                                } else {
                                    "rejected"
                                };
                                let client_id = mux_events.client_id().unwrap_or_default();
                                let resp = result_rpc
                                    .call("$events/result", json!({
                                        "clientId": client_id,
                                        "eventId": event_id,
                                        "outcome": { "kind": "result", "value": value },
                                    }))
                                    .await;
                                eprintln!("[worker] auto decide -> {value}: {resp:?}");
                                let _ = evs.send(Ev::ApprovalGone).await;
                            }
                        } else if event == "user-questions/request" {
                            let req = value.get("request").cloned().unwrap_or(Value::Null);
                            eprintln!("[worker] user questions {event_id}");
                            let _ = evs.send(Ev::Question { event_id, request: req }).await;
                        } else {
                            eprintln!("[worker] waterfall {event}");
                        }
                    }
                    other => {
                        eprintln!(
                            "[worker] events frame type={:?} raw={}",
                            other,
                            value.to_string().chars().take(200).collect::<String>()
                        );
                    }
                }
            }
        });
    }

    let _ = evs
        .send(Ev::DshInfo {
            version: host.version().to_string(),
            bundled: host.bundled(),
        })
        .await;
    let http = host.client().clone();
    let base = host.base().clone();
    let _ = evs.send(Ev::Line("engine ready".into())).await;
    let _ = refresh_sessions(&rpc, &evs).await;

    // workspace/follow：置顶/归档状态的唯一来源（baseline + pinned/archived 增量）
    {
        let mux = mux.clone();
        let evs_ws = evs.clone();
        tokio::spawn(async move {
            let Ok(mut stream) = mux.open("workspace/follow", json!({})).await else {
                return;
            };
            loop {
                match stream.recv().await {
                    Some(Frame::Item(value)) => {
                        let _ = evs_ws.send(Ev::Workspace(value)).await;
                    }
                    _ => break,
                }
            }
        });
    }

    // session/control：全库会话投影（title/权限预设/收件箱队列）的实时来源。
    // 重启恢复 + 侧栏活跃状态都靠它：baseline 一次给全量，之后逐会话增量。
    {
        let mux = mux.clone();
        let evs_ctl = evs.clone();
        tokio::spawn(async move {
            let Ok(mut stream) = mux.open("session/control", json!({})).await else {
                eprintln!("[worker] session/control open failed");
                return;
            };
            eprintln!("[worker] session/control open");
            loop {
                match stream.recv().await {
                    Some(Frame::Item(value)) => {
                        let kind = value.get("type").and_then(|v| v.as_str()).unwrap_or("");
                        let updates: Vec<(String, Value)> = if kind == "baseline" {
                            value
                                .pointer("/value/projections")
                                .and_then(|v| v.as_object())
                                .map(|blocks| {
                                    blocks
                                        .iter()
                                        .map(|(sid, block)| {
                                            (sid.clone(), block.get("values").cloned().unwrap_or(Value::Null))
                                        })
                                        .collect()
                                })
                                .unwrap_or_default()
                        } else if kind == "projection" {
                            // changes 是 [{ key, val }] 数组
                            value
                                .get("sessionId")
                                .and_then(|v| v.as_str())
                                .and_then(|sid| {
                                    let changes = value.get("changes")?.as_array()?;
                                    let mut map = serde_json::Map::new();
                                    for change in changes {
                                        if let (Some(key), Some(val)) = (
                                            change.get("key").and_then(|k| k.as_str()),
                                            change.get("val").cloned(),
                                        ) {
                                            map.insert(key.to_string(), val);
                                        }
                                    }
                                    Some(vec![(sid.to_string(), Value::Object(map))])
                                })
                                .unwrap_or_default()
                        } else {
                            Vec::new()
                        };
                        for (session_id, values) in updates {
                            let _ = evs_ctl
                                .send(Ev::ControlProjection { session_id, values })
                                .await;
                        }
                    }
                    _ => break,
                }
            }
            eprintln!("[worker] session/control ended");
        });
    }

    loop {
        tokio::select! {
            cmd = cmds.recv() => {
                let Ok(cmd) = cmd else { break };
                match cmd {
                    Cmd::ModelCatalog => {
                        match rpc.call("session/modelCatalog", json!({})).await {
                            Ok(value) => {
                                let _ = evs.send(Ev::ModelCatalog(value)).await;
                            }
                            Err(err) => {
                                eprintln!("[worker] modelCatalog failed: {err}");
                            }
                        }
                    }
                    Cmd::SelectModel { provider, model } => {
                        if let Some(session_id) = current.clone() {
                            match rpc
                                .call("session/selectModel", json!({
                                    "request": {
                                        "sessionId": session_id,
                                        "provider": provider,
                                        "model": model,
                                    }
                                }))
                                .await
                            {
                                Ok(_) => {
                                    eprintln!("[worker] selectModel ok: {provider} / {model}");
                                    let _ = evs.send(Ev::ModelSelected {
                                        provider: provider.clone(),
                                        model: model.clone(),
                                    }).await;
                                }
                                Err(err) => {
                                    eprintln!("[worker] selectModel failed: {err}");
                                }
                            }
                        }
                    }
                    Cmd::Refresh => {
                        let _ = refresh_sessions(&rpc, &evs).await;
                    }
                    Cmd::Watch(id) => {
                        if followed.insert(id.clone()) {
                            let mux_f = mux.clone();
                            let frame_tx_f = frame_tx.clone();
                            let evs_f = evs.clone();
                            let sid = id.clone();
                            tokio::spawn(async move {
                                match mux_f
                                    .open("session/follow", json!({
                                        "request": {
                                            "address": { "kind": "session", "sessionId": sid },
                                            "maxMessages": 200,
                                        }
                                    }))
                                    .await
                                {
                                    Ok(mut stream) => loop {
                                        match stream.recv().await {
                                            Some(Frame::Item(value)) => {
                                                if frame_tx_f.send((sid.clone(), value)).await.is_err() {
                                                    break;
                                                }
                                            }
                                            _ => break,
                                        }
                                    },
                                    Err(err) => {
                                        let _ = evs_f.send(Ev::Error(format!("watch failed: {err}"))).await;
                                    }
                                }
                            });
                        }
                    }
                    Cmd::Follow(id) => {
                        let first = followed.insert(id.clone());
                        current = Some(id.clone());
                        let _ = evs.send(Ev::FollowStart(id.clone())).await;
                        if let Ok(value) = rpc
                            .call("session/projections", json!({
                                "request": { "sessionId": id }
                            }))
                            .await
                        {
                            let selection = value
                                .pointer("/values/modelSelection/next")
                                .or_else(|| value.pointer("/values/modelSelection/lastUsed"));
                            if let Some(selection) = selection {
                                let provider = selection
                                    .get("provider")
                                    .and_then(|v| v.as_str())
                                    .unwrap_or("")
                                    .to_string();
                                let model = selection
                                    .get("model")
                                    .and_then(|v| v.as_str())
                                    .unwrap_or("")
                                    .to_string();
                                if !model.is_empty() {
                                    let _ = evs.send(Ev::ModelSelected { provider, model }).await;
                                }
                            }
                        }

                        if !first {
                            continue;
                        }
                        // 每个 session 一个独立 follow；不再用全局 generation 取消。
                        let mux_f = mux.clone();
                        let frame_tx_f = frame_tx.clone();
                        let evs_f = evs.clone();
                        let sid = id.clone();
                        let http_f = http.clone();
                        let base_f = base.clone();
                        tokio::task::spawn(async move {
                            trace(format_args!("[worker] follow task start {sid}"));
                            let mut stream = match mux_f
                                .open("session/follow", json!({
                                    "request": {
                                        "address": { "kind": "session", "sessionId": sid },
                                        "maxMessages": 200,
                                    }
                                }))
                                .await
                            {
                                Ok(s) => s,
                                Err(err) => {
                                    let _ = evs_f.send(Ev::Error(format!("follow failed: {err}"))).await;
                                    return;
                                }
                            };
                            trace(format_args!("[worker] follow stream opened id={}", stream.stream_id));
                            let mut n = 0u64;
                            let mut prompted = false;
                            loop {
                                match stream.recv().await {
                                            Some(Frame::Item(v)) => {
                                                n += 1;
                                                // 调试钩子：DSH_GUI_AUTOPROMPT=<文本> 在 follow 出第一帧后自动发一条
                                                let auto = std::env::var("DSH_GUI_AUTOPROMPT").ok();
                                                if n == 1 && !prompted && auto.is_some() {
                                                    prompted = true;
                                                    let text = auto.unwrap();
                                                    let rpc_f = Rpc::new(&http_f, &base_f);
                                                    let r = rpc_f.call("session/prompt", json!({
                                                        "request": {
                                                            "requestId": format!("auto-{sid}"),
                                                            "sessionId": sid.clone(),
                                                            "mode": "queue",
                                                            "content": [ { "type": "text", "text": text } ],
                                                        }
                                                    })).await;
                                                    eprintln!("[worker] autoprompt: {r:?}");
                                                }
                                                if n == 1 && !prompted && std::env::var("DSH_GUI_SELFTEST").is_ok() {
                                                    prompted = true;
                                                    let rpc_f = Rpc::new(&http_f, &base_f);
                                                    let r = rpc_f.call("session/prompt", json!({
                                                        "request": {
                                                            "requestId": format!("self-{sid}"),
                                                            "sessionId": sid.clone(),
                                                            "mode": "queue",
                                                            "content": [ { "type": "text", "text": "Say: selftest2" } ],
                                                        }
                                                    })).await;
                                                    eprintln!("[worker] selftest prompt: {r:?}");
                                                }

                                                if frame_tx_f.send((sid.clone(), v)).await.is_err() { break; }
                                            }
                                            _ => break,
                                }
                            }
                            trace(format_args!("[worker] follow task EXITED after {n}"));
                        });
                        // 跳过旧的 spawn 块
                        continue;

                        // 调试钩子：DSH_GUI_AUTOPROMPT 时，follow 建立后自动发一条
                        if let Ok(text) = std::env::var("DSH_GUI_AUTOPROMPT") {
                            eprintln!("[worker] autoprompt after follow: {text}");
                            let result = rpc
                                .call("session/prompt", json!({
                                    "request": {
                                        "requestId": format!("omd-auto-{sid}"),
                                        "sessionId": id.clone(),
                                        "mode": "queue",
                                        "content": [ { "type": "text", "text": text } ],
                                    }
                                }))
                                .await;
                            eprintln!("[worker] autoprompt result: {result:?}");
                        }

                        // 独立 task：不在 select 里，避免被 select 的其他分支饿死

                    }
                    Cmd::NewSession { cwd: requested_cwd } => {
                        let cwd = requested_cwd
                            .or_else(|| std::env::var("PWD").ok())
                            .unwrap_or_else(|| "/".into());
                        match rpc
                            .call("session/create", json!({
                                "request": { "cwd": cwd }
                            }))
                            .await
                        {
                            Ok(created) => {
                                if let Some(session_id) = created
                                    .get("sessionId")
                                    .and_then(|v| v.as_str())
                                    .map(|v| v.to_string())
                                {
                                    eprintln!("[worker] created session {session_id}");
                                    let _ = evs
                                        .send(Ev::SessionCreated(session_id.clone()))
                                        .await;
                                    let gen = generation.fetch_add(1, Ordering::SeqCst) + 1;
                                    let _ = follow_gen_tx.send(gen);
                                    current = Some(session_id.clone());
                                    if let Ok(mut stream) = mux
                                        .open("session/follow", json!({
                                            "request": {
                                                "address": { "kind": "session", "sessionId": session_id },
                                            }
                                        }))
                                        .await
                                    {
                                        let frame_tx = frame_tx.clone();
                                        let mut stop_rx = follow_gen_rx.clone();
                                        let sid_task = session_id.clone();
                                        // 本次世代已看过，避免 changed() 立即触发取消。
                                        let _ = stop_rx.borrow_and_update();
                                        tokio::spawn(async move {
                                            loop {
                                                tokio::select! {
                                                    changed = stop_rx.changed() => {
                                                        if changed.is_err() { break; }
                                                        stream.cancel();
                                                        break;
                                                    }
                                                    frame = stream.recv() => {
                                                        match frame {
                                                            Some(Frame::Item(value)) => {
                                                                if frame_tx.send((sid_task.clone(), value)).await.is_err() { break; }
                                                            }
                                                            _ => break,
                                                        }
                                                    }
                                                }
                                            }
                                        });
                                        // 调试钩子：新会话建好后自动发一条（follow 已经打开）
                                        if let Ok(text) = std::env::var("DSH_GUI_AUTOPROMPT") {
                                            let r = rpc
                                                .call("session/prompt", json!({
                                                    "request": {
                                                        "requestId": format!("auto-{gen}"),
                                                        "sessionId": session_id.clone(),
                                                        "mode": "queue",
                                                        "content": [ { "type": "text", "text": text } ],
                                                    }
                                                }))
                                                .await;
                                            eprintln!("[worker] autoprompt(new session): {r:?}");
                                        }
                                        if let Ok(b64) = std::env::var("DSH_GUI_AUTOIMAGE") {
                                            let result = rpc
                                                .call("session/prompt", json!({
                                                    "request": {
                                                        "requestId": format!("img-{gen}"),
                                                        "sessionId": session_id,
                                                        "mode": "queue",
                                                        "content": [
                                                            { "type": "image", "mediaType": "image/png", "data": b64 },
                                                            { "type": "text", "text": "Describe this image in 3 words" }
                                                        ],
                                                    }
                                                }))
                                                .await;
                                            eprintln!("[worker] autoimage prompt: {result:?}");
                                        }
                                        if let Ok(text) = std::env::var("DSH_GUI_AUTOPROMPT") {
                                            let result = rpc
                                                .call("session/prompt", json!({
                                                    "request": {
                                                        "requestId": format!("omd-new-{gen}"),
                                                        "sessionId": session_id,
                                                        "mode": "queue",
                                                        "content": [ { "type": "text", "text": text } ],
                                                    }
                                                }))
                                                .await;
                                            eprintln!("[worker] new-session prompt: {result:?}");
                                        }
                                    }
                                } else {
                                    let _ = evs.send(Ev::Error(format!("create returned {created}"))).await;
                                }
                            }
                            Err(err) => {
                                let _ = evs.send(Ev::Error(format!("session/create failed: {err}"))).await;
                            }
                        }
                        let _ = refresh_sessions(&rpc, &evs).await;
                    }
                    Cmd::NewTerminal {
                        pane_id,
                        kind,
                        cwd,
                        run,
                    } => {
                        let term_cwd = cwd.unwrap_or_else(default_terminal_cwd);
                        eprintln!("[worker] NewTerminal pane={pane_id} cwd={term_cwd}");
                        let session_id = match rpc
                            .call("session/create", json!({ "request": { "cwd": term_cwd } }))
                            .await
                        {
                            Ok(created) => created
                                .get("sessionId")
                                .and_then(|v| v.as_str())
                                .map(|s| s.to_string()),
                            Err(err) => {
                                let hint = if format!("{err}").contains("sending request") {
                                    "（不是 web：这是本地 dsh daemon 的 HTTP API，daemon 可能挂/换端口了，重启 omd 会重新拉起）"
                                } else {
                                    ""
                                };
                                let _ = evs
                                    .send(Ev::Error(format!(
                                        "session/create 失败: {err}{hint}"
                                    )))
                                    .await;
                                None
                            }
                        };
                        let Some(session_id) = session_id else {
                            let _ = evs
                                .send(Ev::Error("终端需要先有会话；上面的失败原因就是它".into()))
                                .await;
                            let _ = evs.send(Ev::PaneAbandoned(pane_id)).await;
                            continue;
                        };
                        let term_id = format!("omd-term-{}", uuid_like());
                        match rpc
                            .call("terminal/create", json!({
                                "agentId": session_id,
                                "request": { "id": term_id.clone(), "cols": 100, "rows": 30 }
                            }))
                            .await
                        {
                            Ok(_) => {
                                eprintln!("[worker] terminal created {} (pane={pane_id})", term_id);
                                let (up_tx, mut up_rx) =
                                    tokio::sync::mpsc::unbounded_channel::<TerminalUp>();
                                terminal_up.lock().await.insert(term_id.clone(), up_tx);
                                let _ = evs
                                    .send(Ev::TerminalSession {
                                        pane_id,
                                        kind,
                                        session_id: session_id.clone(),
                                        term_id: term_id.clone(),
                                    })
                                    .await;

                                // 每个终端一条 attach 流，输出带 term_id 回 UI
                                let mux = mux.clone();
                                let evs_t = evs.clone();
                                let tid = term_id.clone();
                                let agent = session_id.clone();
                                let buf_t = terminal_buffers.clone();
                                tokio::spawn(async move {
                                    let Ok(mut stream) = mux
                                        .open(
                                            "terminal/attach",
                                            json!({ "agentId": agent, "id": tid.clone() }),
                                        )
                                        .await
                                    else {
                                        return;
                                    };
                                    let mut seq: u64 = 0;
                                    seq += 1;
                                    stream.send_item(json!({
                                        "type": "write",
                                        "sequence": seq,
                                        "data": terminal_browser_prelude(),
                                    }));
                                    // 需要的话，先把命令敲进去（TUI 之类）
                                    if let Some(command) = run {
                                        seq += 1;
                                        stream.send_item(json!({
                                            "type": "write",
                                            "sequence": seq,
                                            "data": format!("{command}\r"),
                                        }));
                                    }
                                    loop {
                                        tokio::select! {
                                            item = up_rx.recv() => {
                                                let Some(item) = item else { break };
                                                seq += 1;
                                                match item {
                                                    TerminalUp::Write(data) => stream.send_item(json!({
                                                        "type": "write", "sequence": seq, "data": data,
                                                    })),
                                                    TerminalUp::Resize(cols, rows) => stream.send_item(json!({
                                                        "type": "resize", "sequence": seq, "cols": cols, "rows": rows,
                                                    })),
                                                }
                                            }
                                            frame = stream.recv() => {
                                                match frame {
                                                    Some(Frame::Item(v)) => {
                                                        let frame_type = v.get("type").and_then(|t| t.as_str());
                                                        if matches!(frame_type, Some("snapshot") | Some("output")) {
                                                            let data = if frame_type == Some("snapshot") {
                                                                v.get("screen").and_then(|d| d.as_str()).unwrap_or_default().to_string()
                                                            } else {
                                                                v.get("data").and_then(|d| d.as_str()).unwrap_or_default().to_string()
                                                            };
                                                            if !data.is_empty() {
                                                                let mut buffers = buf_t.lock().await;
                                                                let entry = buffers
                                                                    .entry(tid.clone())
                                                                    .or_insert_with(String::new);
                                                                entry.push_str(&data);
                                                                if entry.len() > 2_000_000 {
                                                                    let cut = entry.len() - 2_000_000;
                                                                    entry.drain(..cut);
                                                                }
                                                            }
                                                            let _ = evs_t
                                                                .send(Ev::TerminalOutput {
                                                                    term_id: tid.clone(),
                                                                    data,
                                                                })
                                                                .await;
                                                        }
                                                    }
                                                    _ => break,
                                                }
                                            }
                                        }
                                    }
                                });
                            }
                            Err(err) => {
                                let _ = evs
                                    .send(Ev::Error(format!("terminal/create failed: {err}")))
                                    .await;
                                let _ = evs.send(Ev::PaneAbandoned(pane_id)).await;
                            }
                        }
                    }
                    Cmd::AttachTerminal {
                        pane_id,
                        session_id,
                        term_id,
                    } => {
                        eprintln!("[worker] AttachTerminal pane={pane_id} term={term_id}");
                        let (up_tx, mut up_rx) =
                            tokio::sync::mpsc::unbounded_channel::<TerminalUp>();
                        terminal_up.lock().await.insert(term_id.clone(), up_tx);
                        let mux_t = mux.clone();
                        let evs_t = evs.clone();
                        let buf_t = terminal_buffers.clone();
                        let tid = term_id.clone();
                        let agent = session_id.clone();
                        tokio::spawn(async move {
                            let Ok(mut stream) = mux_t
                                .open("terminal/attach", json!({ "agentId": agent, "id": tid.clone() }))
                                .await
                            else {
                                let _ = evs_t
                                    .send(Ev::Error(format!("terminal attach failed: {tid}")))
                                    .await;
                                return;
                            };
                            let mut seq = 0u64;
                            loop {
                                tokio::select! {
                                    item = up_rx.recv() => {
                                        let Some(item) = item else { break };
                                        seq += 1;
                                        match item {
                                            TerminalUp::Write(data) => stream.send_item(json!({
                                                "type": "write", "sequence": seq, "data": data,
                                            })),
                                            TerminalUp::Resize(cols, rows) => stream.send_item(json!({
                                                "type": "resize", "sequence": seq, "cols": cols, "rows": rows,
                                            })),
                                        }
                                    }
                                    frame = stream.recv() => {
                                        match frame {
                                            Some(Frame::Item(value)) => {
                                                let frame_type = value.get("type").and_then(|v| v.as_str());
                                                if !matches!(frame_type, Some("snapshot") | Some("output")) {
                                                    continue;
                                                }
                                                let data = if frame_type == Some("snapshot") {
                                                    value.get("screen").and_then(|v| v.as_str()).unwrap_or_default().to_string()
                                                } else {
                                                    value.get("data").and_then(|v| v.as_str()).unwrap_or_default().to_string()
                                                };
                                                if data.is_empty() {
                                                    continue;
                                                }
                                                let mut buffers = buf_t.lock().await;
                                                let entry = buffers.entry(tid.clone()).or_insert_with(String::new);
                                                entry.push_str(&data);
                                                if entry.len() > 2_000_000 {
                                                    let cut = entry.len() - 2_000_000;
                                                    entry.drain(..cut);
                                                }
                                                drop(buffers);
                                                let _ = evs_t
                                                    .send(Ev::TerminalOutput { term_id: tid.clone(), data })
                                                    .await;
                                            }
                                            _ => break,
                                        }
                                    }
                                }
                            }
                        });
                    }
                    Cmd::JobsWatch { session_id } => {
                        let gen = jobs_gen.fetch_add(1, Ordering::SeqCst) + 1;
                        let Some(session_id) = session_id else { continue };
                        let mux = mux.clone();
                        let evs_jobs = evs.clone();
                        let gen_ref = jobs_gen.clone();
                        tokio::spawn(async move {
                            let Ok(mut stream) = mux
                                .open("job/list", json!({ "request": { "sessionId": session_id } }))
                                .await
                            else {
                                return;
                            };
                            loop {
                                if gen_ref.load(Ordering::SeqCst) != gen {
                                    break;
                                }
                                match stream.recv().await {
                                    Some(Frame::Item(v)) => {
                                        let _ = evs_jobs.send(Ev::Jobs(v)).await;
                                    }
                                    _ => break,
                                }
                            }
                        });
                    }
                    Cmd::JobKill {
                        session_id,
                        job_id,
                    } => {
                        let r = rpc
                            .call(
                                "job/kill",
                                json!({
                                    "request": { "sessionId": session_id, "jobId": job_id }
                                }),
                            )
                            .await;
                        eprintln!("[worker] job/kill {job_id}: {r:?}");
                    }
                    Cmd::Call {
                        tag,
                        endpoint,
                        args,
                    } => {
                        let r = rpc.call(&endpoint, args).await;
                        let _ = evs
                            .send(Ev::Called {
                                tag,
                                endpoint,
                                result: r.map_err(|e| e.to_string()),
                            })
                            .await;
                    }
                    Cmd::ForkSession { session_id, at_seq } => {
                        let mut request = json!({ "sessionId": session_id });
                        if let Some(at_seq) = at_seq {
                            request["atSeq"] = json!(at_seq);
                        }
                        match rpc
                            .call("session/fork", json!({ "request": request }))
                            .await
                        {
                            Ok(value) => {
                                if let Some(new_id) =
                                    value.get("sessionId").and_then(|v| v.as_str())
                                {
                                    eprintln!("[worker] forked {session_id} -> {new_id}");
                                    let _ = evs.send(Ev::SessionCreated(new_id.to_string())).await;
                                } else {
                                    let _ = evs
                                        .send(Ev::Error(format!(
                                            "fork returned no session id: {value}"
                                        )))
                                        .await;
                                }
                            }
                            Err(err) => {
                                let _ = evs.send(Ev::Error(format!("fork failed: {err}"))).await;
                            }
                        }
                    }
                    Cmd::InstallPlugin {
                        name,
                        spec,
                        registry,
                        request_id,
                        approved_builds,
                    } => {
                        // 安装可能跑几分钟：放到独立任务里，让 CancelInstall
                        // 能穿过命令循环立刻送达。
                        let http = http.clone();
                        let base = base.clone();
                        let evs = evs.clone();
                        tokio::spawn(async move {
                            let rpc = Rpc::new(&http, &base);
                            let mut options = json!({ "requestId": request_id, "enabled": true });
                            if let Some(registry) = registry {
                                options["registry"] = json!(registry);
                            }
                            if let Some(builds) = approved_builds {
                                options["approvedBuilds"] = json!(builds);
                            }
                            let r = rpc
                                .call("pluginManager/installBundle", json!({
                                    "spec": spec,
                                    "options": options,
                                }))
                                .await;
                            let _ = evs
                                .send(Ev::InstallSettled {
                                    name,
                                    result: r.map_err(|e| e.to_string()),
                                })
                                .await;
                        });
                    }
                    Cmd::CancelInstall { request_id } => {
                        match rpc
                            .call("pluginManager/cancelInstall", json!({
                                "requestId": request_id
                            }))
                            .await
                        {
                            Ok(value) => {
                                eprintln!("[worker] cancelInstall {request_id}: {value}");
                            }
                            Err(err) => {
                                let _ = evs
                                    .send(Ev::Error(format!("cancel install failed: {err}")))
                                    .await;
                            }
                        }
                    }
                    Cmd::PickFiles => {
                        let evs = evs.clone();
                        tokio::task::spawn_blocking(move || {
                            let mut picked: Vec<String> = Vec::new();
                            let zenity = std::process::Command::new("zenity")
                                .args([
                                    "--file-selection",
                                    "--multiple",
                                    "--separator=|",
                                    "--title=Attach files",
                                ])
                                .output();
                            match zenity {
                                Ok(output) if output.status.success() => {
                                    let text = String::from_utf8_lossy(&output.stdout);
                                    picked.extend(
                                        text.split('|')
                                            .map(str::trim)
                                            .filter(|p| !p.is_empty())
                                            .map(str::to_string),
                                    );
                                }
                                Ok(_) => {}
                                Err(_) => {
                                    // 没有 zenity 就试 kdialog（只支持单文件）
                                    if let Ok(output) = std::process::Command::new("kdialog")
                                        .args(["--getopenfilename", ".", "*"])
                                        .output()
                                    {
                                        if output.status.success() {
                                            let text = String::from_utf8_lossy(&output.stdout)
                                                .trim()
                                                .to_string();
                                            if !text.is_empty() {
                                                picked.push(text);
                                            }
                                        }
                                    }
                                }
                            }
                            let _ = evs.send_blocking(Ev::FilesPicked(picked));
                        });
                    }
                    Cmd::TerminalInput { term_id, data } => {
                        let found = terminal_up.lock().await.get(&term_id).is_some();
                        eprintln!("[worker] TerminalInput term={term_id} found={found} bytes={}", data.len());
                        if let Some(tx) = terminal_up.lock().await.get(&term_id) {
                            let _ = tx.send(TerminalUp::Write(data));
                        }
                    }
                    Cmd::Cancel => {
                        if let Some(session_id) = current.clone() {
                            match rpc
                                .call("session/cancel", json!({
                                    "request": { "sessionId": session_id }
                                }))
                                .await
                            {
                                Ok(_) => {
                                    eprintln!("[worker] cancel accepted");
                                    let _ = evs.send(Ev::Line("(cancelled)".into())).await;
                                }
                                Err(err) => {
                                    let _ = evs.send(Ev::Error(format!("cancel failed: {err}"))).await;
                                }
                            }
                        }
                    }
                    Cmd::CancelSession(session_id) => {
                        if !session_id.is_empty() && !is_file_panel(&session_id) {
                            match rpc
                                .call("session/cancel", json!({
                                    "request": { "sessionId": session_id }
                                }))
                                .await
                            {
                                Ok(_) => eprintln!("[worker] cancel accepted for {session_id}"),
                                Err(err) => eprintln!("[worker] cancel {session_id} failed: {err}"),
                            }
                        }
                    }
                    Cmd::UpdateDsh => {
                        let evs = evs.clone();
                        tokio::spawn(async move {
                            let _ = evs
                                .send(Ev::DshUpdate {
                                    done: false,
                                    message: "downloading and installing dsh…".into(),
                                })
                                .await;
                            match dsh_host::install_dsh("latest").await {
                                Ok(runtime) => {
                                    let _ = evs
                                        .send(Ev::DshUpdate {
                                            done: true,
                                            message: format!(
                                                "Updated to v{}. Restart the app to apply.",
                                                runtime.version
                                            ),
                                        })
                                        .await;
                                }
                                Err(err) => {
                                    let _ = evs
                                        .send(Ev::DshUpdate {
                                            done: true,
                                            message: format!("update failed: {err}"),
                                        })
                                        .await;
                                }
                            }
                        });
                    }
                    Cmd::AnswerQuestion { event_id, answer } => {
                        let client_id = mux.client_id().unwrap_or_default();
                        let payload = json!({
                            "clientId": client_id,
                            "eventId": event_id,
                            "outcome": { "kind": "result", "value": answer },
                        });
                        match rpc.call("$events/result", payload).await {
                            Ok(_) => {
                                eprintln!("[worker] question answered");
                                let _ = evs.send(Ev::QuestionGone).await;
                            }
                            Err(err) => {
                                let _ = evs.send(Ev::Error(format!("question answer failed: {err}"))).await;
                            }
                        }
                    }
                    Cmd::Decide { event_id, allow } => {
                        let outcome = if allow { "allowed-once" } else { "rejected" };
                        let client_id = mux.client_id().unwrap_or_default();
                        let payload = json!({
                            "clientId": client_id,
                            "eventId": event_id,
                            "outcome": { "kind": "result", "value": outcome },
                        });
                        match rpc.call("$events/result", payload).await {
                            Ok(_) => {
                                eprintln!("[worker] decision sent: {outcome}");
                                let _ = evs.send(Ev::ApprovalGone).await;
                            }
                            Err(err) => {
                                let _ = evs.send(Ev::Error(format!("decide failed: {err}"))).await;
                            }
                        }
                    }
                    Cmd::Prompt { session_id, text, request_id, extra } => {
                        eprintln!("[worker] Prompt cmd, session={session_id}");
                        // follow 回放这条消息时带同一个 source.rpcId，用它压掉本地回显。
                        pending_echoes.push_back(request_id.clone());
                        if pending_echoes.len() > 16 {
                            pending_echoes.pop_front();
                        }
                        prompt_started = Some(std::time::Instant::now());
                        let mut content: Vec<Value> = Vec::new();
                        if !text.trim().is_empty() {
                            content.push(json!({ "type": "text", "text": text }));
                        }
                        content.extend(extra);
                        let result = rpc
                            .call("session/prompt", json!({
                                "request": {
                                    "requestId": request_id,
                                    "sessionId": session_id,
                                    "mode": "queue",
                                    "content": content,
                                }
                            }))
                            .await;
                        match result {
                            Ok(value) => {
                                trace(format_args!("[worker] prompt accepted: {value}"));
                            }
                            Err(err) => {
                                prompt_started = None;
                                let _ = evs.send(Ev::Error(format!("prompt failed: {err}"))).await;
                            }
                        }
                    }
                    Cmd::UploadFile {
                        attach_id,
                        agent_id,
                        name,
                        data,
                    } => {
                        use base64::Engine as _;
                        let encoded =
                            base64::engine::general_purpose::STANDARD.encode(data.as_slice());
                        let result = rpc
                            .call("fileUploads/upload", json!({
                                "agentId": agent_id,
                                "request": { "data": encoded, "name": name },
                            }))
                            .await
                            .map_err(|e| e.to_string());
                        let _ = evs
                            .send(Ev::FileStaged { attach_id, result })
                            .await;
                    }
                }
            }
            frame = frame_rx.recv() => {
                if let Ok((session_id, mut value)) = frame {
                    if std::env::var("OMD_TRACE_TOOLS").is_ok() {
                        let raw = serde_json::to_string(&value).unwrap_or_default();
                        eprintln!(
                            "[trace] frame session={session_id} {}",
                            &raw.chars().take(160).collect::<String>()
                        );
                    }
                    {
                        if let Some(kind) = value.get("type").and_then(|v| v.as_str()) {
                            if kind == "assistant-stream" {
                                let frame = value.get("frame").cloned().unwrap_or(Value::Null);
                                match frame.get("type").and_then(|v| v.as_str()) {
                                    Some("start") => {
                                        let _ = evs.send(Ev::StreamStart { session_id: session_id.clone() }).await;
                                    }
                                    Some("chunk") => {
                                        let chunk = frame.get("chunk").cloned().unwrap_or(Value::Null);
                                        let chunk_type =
                                            chunk.get("type").and_then(|v| v.as_str()).unwrap_or("");
                                        if matches!(chunk_type, "text-delta" | "reasoning-delta") {
                                            if let Some(started) = prompt_started.take() {
                                                eprintln!(
                                                    "[perf] first token: {}ms",
                                                    started.elapsed().as_millis()
                                                );
                                            }
                                        }
                                        if chunk_type == "text-delta" {
                                            if let Some(text) =
                                                chunk.get("text").and_then(|v| v.as_str())
                                            {
                                                let _ = evs.send(Ev::StreamDelta { session_id: session_id.clone(), delta: text.to_string() }).await;
                                            }
                                        } else if chunk_type == "reasoning-delta" {
                                            if let Some(text) =
                                                chunk.get("text").and_then(|v| v.as_str())
                                            {
                                                let _ = evs.send(Ev::ReasoningDelta { session_id: session_id.clone(), delta: text.to_string() }).await;
                                            }
                                        }
                                    }
                                    _ => {}
                                }
                                continue;
                            }
                        }
                        let event_type = value
                            .get("event")
                            .and_then(|e| e.get("type"))
                            .and_then(|v| v.as_str());
                        // 用户消息已本地回显：同 rpcId 的 follow 事件不再重复上屏。
                        let mut skip_echo = false;
                        if event_type == Some("user/message") {
                            if let Some(rpc_id) = value
                                .pointer("/event/data/source/rpcId")
                                .and_then(|v| v.as_str())
                            {
                                if let Some(pos) = pending_echoes.iter().position(|id| id == rpc_id) {
                                    pending_echoes.remove(pos);
                                    skip_echo = true;
                                }
                            }
                        }
                        // 图片消息：拉 attachment base64
                        if matches!(event_type, Some("user/message") | Some("assistant/message") | Some("tool/result")) {
                            if let Some(content) = value.pointer("/event/data/content").and_then(|c| c.as_array()) {
                                let session_id_img = current.clone().unwrap_or_default();
                                for block in content {
                                    if block.get("type").and_then(|t| t.as_str()) == Some("image") {
                                        let Some(att_id) = block.pointer("/attachment/attachmentId").and_then(|v| v.as_str()) else { continue };
                                        if att_id.is_empty() || session_id_img.is_empty() { continue; }
                                        let att_id = att_id.to_string();
                                        let rpc_img = http.clone();
                                        let base_img = base.clone();
                                        let evs_img = evs.clone();
                                        let sid_img = session_id_img.clone();
                                        tokio::spawn(async move {
                                            let rpc = Rpc::new(&rpc_img, &base_img);
                                            let payload = json!({
                                                "request": { "sessionId": sid_img, "attachmentId": att_id }
                                            });
                                            if let Ok(resp) = rpc.call("session/attachment", payload).await {
                                                if let Some(b64) = resp.get("data").and_then(|d| d.as_str()) {
                                                    let _ = evs_img.send(Ev::ImageB64(b64.to_string())).await;
                                                }
                                            }
                                        });
                                    }
                                }
                            }
                        }
                        if event_type == Some("assistant/message") {
                            let _ = evs.send(Ev::StreamEnd { session_id: session_id.clone() }).await;
                        }
                        if event_type == Some("turn/start") {
                            let _ = evs.send(Ev::AgentRunning(true)).await;
                        }
                        if event_type == Some("turn/end") {
                            let _ = evs.send(Ev::AgentRunning(false)).await;
                        }
                        stamp_tool_elapsed(&mut value, &mut tool_started);
                        if !skip_echo {
                            let _ = evs.send(Ev::Event { session_id: session_id.clone(), value: value.clone() }).await;
                        }
                    }
                }
            }
        }
    }

}

async fn refresh_sessions(rpc: &Rpc<'_>, evs: &Sender<Ev>) {
    match rpc.call("session/list", json!({ "_request": {} })).await {
        Ok(value) => {
            let rows = value
                .get("items")
                .and_then(|v| v.as_array())
                .map(|items| {
                    items
                        .iter()
                        .filter_map(|item| {
                            let id = item.get("sessionId")?.as_str()?.to_string();
                            let cwd = item
                                .get("cwd")
                                .and_then(|v| v.as_str())
                                .unwrap_or("")
                                .to_string();
                            let title = item
                                .get("title")
                                .and_then(|v| v.as_str())
                                .or_else(|| {
                                    item.pointer("/projections/values/title")
                                        .and_then(|v| v.as_str())
                                })
                                .or_else(|| item.pointer("/projections/title").and_then(|v| v.as_str()))
                                .unwrap_or("")
                                .to_string();
                            let blank = item
                                .get("blank")
                                .and_then(|v| v.as_bool())
                                .unwrap_or(false);
                            let updated_at = item
                                .get("updatedAt")
                                .and_then(|v| v.as_i64())
                                .unwrap_or(0);
                            let running = item
                                .get("running")
                                .and_then(|v| v.as_bool())
                                .unwrap_or(false);
                            let parent = item
                                .get("parentSessionId")
                                .and_then(|v| v.as_str())
                                .map(str::to_string);
                            Some(SessionRow {
                                id,
                                cwd,
                                title,
                                running,
                                blank,
                                updated_at,
                                parent,
                            })
                        })
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            save_sessions_cache(&rows);
            let _ = evs.send(Ev::DshSessions(rows)).await;
        }
        Err(err) => {
            let _ = evs.send(Ev::Error(format!("session/list failed: {err}"))).await;
        }
    }
}

/// host 在每轮注入的context，不是用户输入。
fn is_injected(text: &str) -> bool {
    const MARKERS: [&str; 5] = [
        "<system-reminder>",
        "Current runtime context",
        "Current working directory:",
        "Time sampled while preparing turn",
        "Elapsed since the preceding model-visible message",
    ];
    MARKERS.iter().any(|m| text.contains(m))
}

fn extract_text(data: &Value) -> String {
    let mut out = String::new();
    if let Some(content) = find_content(data) {
        push_blocks(content, &mut out);
    }
    out
}

/// 在事件 data 里找第一个 `content` 键（消息体的规范位置）。
fn find_content(value: &Value) -> Option<&Value> {
    let mut queue: Vec<&Value> = vec![value];
    while let Some(node) = queue.pop() {
        match node {
            Value::Object(map) => {
                if let Some(content) = map.get("content") {
                    return Some(content);
                }
                for child in map.values() {
                    if child.is_object() || child.is_array() {
                        queue.push(child);
                    }
                }
            }
            Value::Array(items) => {
                for child in items {
                    if child.is_object() || child.is_array() {
                        queue.push(child);
                    }
                }
            }
            _ => {}
        }
    }
    None
}

fn push_blocks(node: &Value, out: &mut String) {
    match node {
        Value::Array(items) => {
            for item in items {
                push_blocks(item, out);
            }
        }
        Value::Object(map) => {
            let kind = map.get("type").and_then(|t| t.as_str());
            if kind != Some("text") {
                // reasoning / tool_use / image 等块不当作正文
                return;
            }
            if let Some(text) = map.get("text").and_then(|t| t.as_str()) {
                if !out.is_empty() {
                    out.push('\n');
                }
                out.push_str(text);
            }
        }
        Value::String(text) => {
            if !out.is_empty() {
                out.push('\n');
            }
            out.push_str(text);
        }
        _ => {}
    }
}

