// UI
// ---------------------------------------------------------------------------

#[derive(Clone)]
enum TranscriptBlock {
    User { uid: u64, text: String, seq: Option<u64> },
    Assistant {
        uid: u64,
        text: String,
        /// 可反馈的 assistant 消息 id（流式快照里可能没有）
        message_id: Option<String>,
        /// 事件 seq（fork 边界用）
        seq: Option<u64>,
    },
    Reasoning { uid: u64, text: String, expanded: bool },
    Tool {
        uid: u64,
        call_id: String,
        name: String,
        summary: String,
        args: String,
        output: Option<String>,
        is_error: bool,
        running: bool,
        expanded: bool,
        /// 从 tool/call 到 tool/result 的耗时（我们自己量的）
        duration_ms: Option<u64>,
        /// 从输出里 best-effort 解析出的退出码（dsh 不提供这个字段）
        exit_code: Option<i32>,
    },
    Image(Arc<RenderImage>),
    Notice(String),
}

#[derive(Clone)]
struct StreamState {
    /// 已收到的全部文本（可能比显示的多）
    text: String,
    /// 已收到的字符总数（增量维护，避免每帧 chars().count()）
    total_chars: usize,
    /// 已经"打"出来的字符数
    revealed: usize,
    reasoning: String,
    /// 流是否已结束（结束后把尾巴吐完就收尾）
    ended: bool,
    /// 打字机 ticker 是否在跑
    ticking: bool,
}

impl Default for StreamState {
    fn default() -> Self {
        Self {
            text: String::new(),
            total_chars: 0,
            revealed: 0,
            reasoning: String::new(),
            ended: false,
            ticking: false,
        }
    }
}

/// 对"一条完整回复"做逐字显示（dsh 有时不推 text-delta，只有最终 message）。
struct Typing {
    uid: u64,
    total: usize,
    revealed: usize,
    ticking: bool,
}

impl StreamState {
    /// 当前应该显示的前缀（逐字打出来的部分）。
    fn revealed_text(&self) -> String {
        if self.revealed >= self.total_chars {
            self.text.clone()
        } else {
            self.text.chars().take(self.revealed).collect()
        }
    }
}

#[derive(Clone)]
struct QuestionOption {
    label: String,
    description: Option<String>,
}

#[derive(Clone)]
struct QuestionItem {
    id: String,
    header: Option<String>,
    question: String,
    detail: Option<String>,
    options: Vec<QuestionOption>,
    multi: bool,
}

#[derive(Clone)]
struct PendingQuestion {
    event_id: String,
    call_id: Option<String>,
    questions: Vec<QuestionItem>,
    selected: Vec<Vec<String>>,
}

static NEXT_BLOCK_UID: AtomicU64 = AtomicU64::new(1);

fn block_uid() -> u64 {
    NEXT_BLOCK_UID.fetch_add(1, Ordering::SeqCst)
}

/// 一个包安装的进行状态（市场 / bundle 安装按钮用）。
#[derive(Clone, Debug)]
struct InstallState {
    /// installBundle 的 requestId（取消用）
    request_id: String,
    /// 安装的 spec（重试用）
    spec: String,
    registry: Option<String>,
    status: InstallStatus,
}

#[derive(Clone, Debug)]
enum InstallStatus {
    Running,
    /// 完成（附一句人话摘要）
    Done(String),
    /// 失败（附错误摘要）
    Failed(String),
    /// 需要批准构建脚本：包名列表
    NeedsBuilds(Vec<String>),
}

/// 一条已存在的消息反馈（messageFeedback/list 的 item）。
#[derive(Clone, Debug)]
struct FeedbackState {
    rating: String,
    version: String,
}

/// 终端回滚搜索条：一个终端 pane 一份。
struct TermFind {
    pane_id: u64,
    input: Entity<InputState>,
    /// 上次提交的搜索词（变了才重设 needle）
    query: String,
    index: usize,
    total: usize,
    _sub: Subscription,
}

/// 待发送的附件（图片内联、其他文件先 staging 成 receipt）。
#[derive(Clone, Debug)]
struct PendingAttachment {
    id: u64,
    name: String,
    /// 原始字节（图片直接 base64 进 prompt）
    data: Arc<Vec<u8>>,
    /// Some = 内联图片（media type）
    media_type: Option<String>,
    /// 上传完成后拿到的 staging receipt
    receipt_id: Option<String>,
    state: AttachmentState,
}

#[derive(Clone, Debug, PartialEq)]
enum AttachmentState {
    Uploading,
    Ready,
    Failed(String),
}

