    /// 打开某个终端 pane 的回滚搜索条。
    fn term_find_open(&mut self, pane_id: u64, window: &mut Window, cx: &mut Context<Self>) {
        if !self
            .panes
            .iter()
            .any(|pane| pane.id == pane_id && pane.term.is_some())
        {
            return;
        }
        if let Some(find) = &self.term_find {
            if find.pane_id == pane_id {
                find.input.read(cx).focus_handle(cx).focus(window, cx);
                return;
            }
        }
        let input = cx.new(|cx| {
            InputState::new(window, cx).placeholder("Find in scrollback…")
        });
        let sub = cx.subscribe(&input, |this, _entity, ev: &InputEvent, cx| {
            if let InputEvent::PressEnter { shift, .. } = ev {
                this.term_find_step(*shift, cx);
            }
        });
        self.term_find = Some(TermFind {
            pane_id,
            input,
            query: String::new(),
            index: 0,
            total: 0,
            _sub: sub,
        });
        if let Some(find) = &self.term_find {
            find.input.read(cx).focus_handle(cx).focus(window, cx);
        }
        cx.notify();
    }

    /// Enter：下一个（更旧）；Shift+Enter：上一个。查询词变了就重设并先跑一遍。
    fn term_find_step(&mut self, forward: bool, cx: &mut Context<Self>) {
        let Some((pane_id, query)) = self.term_find.as_ref().map(|find| {
            (
                find.pane_id,
                find.input.read(cx).value().trim().to_string(),
            )
        }) else {
            return;
        };
        let Some(pane) = self.panes.iter_mut().find(|pane| pane.id == pane_id) else {
            self.term_find = None;
            cx.notify();
            return;
        };
        let Some(term) = pane.term.as_mut() else {
            self.term_find = None;
            cx.notify();
            return;
        };
        if query.is_empty() {
            if let Some(find) = self.term_find.as_mut() {
                find.total = 0;
                find.index = 0;
            }
            cx.notify();
            return;
        }
        let changed = self
            .term_find
            .as_ref()
            .is_some_and(|find| query != find.query);
        if changed {
            term.search_set_needle(&query);
            term.search_run();
        }
        let hit = term.search_select(forward);
        pane.screen = term.render_rows();
        pane.images = term.images().to_vec();
        let (index, total) = hit.map(|(i, t)| (i + 1, t)).unwrap_or((0, 0));
        if let Some(find) = self.term_find.as_mut() {
            find.query = query;
            find.index = index;
            find.total = total;
        }
        cx.notify();
    }

    /// 终端粘贴（Ctrl+Shift+V）：剪贴板里有图就贴图（kitty 协议，本地显示），    /// 有文本就按 bracketed 模式编码后写 PTY。返回是否处理了。
    /// 终端格坐标换算（pane body 内边距 8px）。
    fn term_cell_at(&self, pane_id: u64, position: Point<Pixels>) -> Option<(u16, u32)> {
        let bounds = self.pane_bounds.get(&pane_id)?;
        let pad = 8.;
        let x = (f32::from(position.x - bounds.origin.x) - pad) / CELL_W as f32;
        let y = (f32::from(position.y - bounds.origin.y) - pad) / CELL_H as f32;
        if x < 0. || y < 0. {
            return None;
        }
        Some((x as u16, y as u32))
    }

    /// 选区落定（松开鼠标）：拖动过就复制到剪贴板；只是点击就清空。
    fn term_select_end(&mut self, pane_id: u64, cx: &mut Context<Self>) {
        let (_, dragged) = self.term_select.take().unwrap_or((pane_id, false));
        let Some(pane) = self.panes.iter_mut().find(|pane| pane.id == pane_id) else {
            return;
        };
        let Some(term) = pane.term.as_mut() else {
            return;
        };
        if dragged && term.selection_active() {
            if let Some(text) = term.selection_text() {
                if !text.trim().is_empty() {
                    cx.write_to_clipboard(ClipboardItem::new_string(text));
                }
            }
            pane.screen = term.render_rows();
        } else {
            term.selection_clear();
            pane.screen = term.render_rows();
        }
        pane.images = term.images().to_vec();
        cx.notify();
    }

    /// 复制当前终端选区（Ctrl+Shift+C）。返回是否复制到了。
    fn term_copy_selection(&mut self, cx: &mut Context<Self>) -> bool {
        let pane_id = self.term_select.map(|(id, _)| id).or(self.focused_pane);
        let Some(pane_id) = pane_id else {
            return false;
        };
        let Some(pane) = self.panes.iter_mut().find(|pane| pane.id == pane_id) else {
            return false;
        };
        let Some(term) = pane.term.as_mut() else {
            return false;
        };
        if !term.selection_active() {
            return false;
        }
        let Some(text) = term.selection_text() else {
            return false;
        };
        if text.trim().is_empty() {
            return false;
        }
        cx.write_to_clipboard(ClipboardItem::new_string(text));
        true
    }

    /// 切换当前会话的权限预设（走 /permission 命令，事件回填 pill）。
    fn set_permission_preset(&mut self, preset: &str) {
        let Some(agent_id) = self.selected.clone() else {
            return;
        };
        if is_file_panel(&agent_id) || self.term_tabs.contains(&agent_id) {
            return;
        }
        let _ = self.cmds.send_blocking(Cmd::Call {
            tag: "permission/set".to_string(),
            endpoint: "commands/execute".to_string(),
            args: json!({
                "agentId": agent_id,
                "line": format!("/permission {preset}"),
                "submittedAttachments": [],
            }),
        });
    }

    fn term_paste(&mut self, pane_id: u64, cx: &mut Context<Self>) -> bool {
        let Some(item) = cx.read_from_clipboard() else {
            return false;
        };
        let entries: Vec<_> = item.entries().to_vec();
        // 图片优先
        for entry in &entries {
            let ClipboardEntry::Image(image) = entry else {
                continue;
            };
            if let Some(frame) = image::load_from_memory(&image.bytes).ok() {
                let rgba = frame.to_rgba8();
                let (width, height) = (rgba.width(), rgba.height());
                if let Some(pane) = self.panes.iter_mut().find(|pane| pane.id == pane_id) {
                    if let Some(term) = pane.term.as_mut() {
                        term.paste_image_rgba(width, height, rgba.as_raw());
                        pane.screen = term.render_rows();
                        pane.images = term.images().to_vec();
                        cx.notify();
                        return true;
                    }
                }
            }
        }
        // 文本粘贴
        if let Some(text) = item.text() {
            if text.is_empty() {
                return false;
            }
            if let Some(pane) = self.panes.iter().find(|pane| pane.id == pane_id) {
                if !pane.term_id.is_empty() {
                    let term_id = pane.term_id.clone();
                    if let Some(term) = pane.term.as_ref() {
                        let bytes = term.paste_text(&text);
                        if !bytes.is_empty() {
                            let data = String::from_utf8_lossy(&bytes).to_string();
                            let _ = self.cmds.send_blocking(Cmd::TerminalInput { term_id, data });
                            return true;
                        }
                    }
                }
            }
        }
        false
    }

    /// 往前翻一页旧消息（session/page）。
    fn load_older_messages(&mut self, cx: &mut Context<Self>) {
        let Some(session_id) = self.selected.clone() else {
            return;
        };
        let (Some(cursor), Some(before)) = (self.history_cursor, self.history_oldest) else {
            self.history_has_more = false;
            return;
        };
        if self.history_loading {
            return;
        }
        self.history_loading = true;
        let _ = self.cmds.send_blocking(Cmd::Call {
            tag: "session/page".to_string(),
            endpoint: "session/page".to_string(),
            args: json!({
                "request": {
                    "address": { "kind": "session", "sessionId": session_id },
                    "throughSeq": cursor,
                    "beforeSeq": before,
                    "maxMessages": 60,
                }
            }),
        });
        cx.notify();
    }

    /// 滚一个终端 pane 的视口并重绘。
    fn term_scroll(&mut self, pane_id: u64, delta: isize, cx: &mut Context<Self>) {
        if delta == 0 {
            return;
        }
        if let Some(pane) = self.panes.iter_mut().find(|pane| pane.id == pane_id) {
            if let Some(term) = pane.term.as_mut() {
                term.scroll_rows(delta);
                pane.screen = term.render_rows();
                pane.images = term.images().to_vec();
                cx.notify();
            }
        }
    }

    /// 关掉搜索条（清 needle，焦点回终端）。
    fn term_find_close(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if let Some(find) = self.term_find.take() {
            if let Some(pane) = self
                .panes
                .iter_mut()
                .find(|pane| pane.id == find.pane_id)
            {
                if let Some(term) = pane.term.as_mut() {
                    term.search_clear();
                    term.scroll_to_bottom();
                    pane.screen = term.render_rows();
                    pane.images = term.images().to_vec();
                }
                pane.focus.focus(window, cx);
            }
            cx.notify();
        }
    }

    /// 给选中的子代理发一条消息（排队到下一轮）。
