/// LocalizedText：字符串或 {en: …, zh: …}。优先中文，其次 en，其次任意。
fn localized_text(value: &Value) -> Option<String> {
    match value {
        Value::String(text) => Some(text.clone()),
        Value::Object(map) => {
            let pick = map
                .get("zh")
                .or_else(|| map.get("en"))
                .and_then(|v| v.as_str())
                .map(str::to_string);
            pick.or_else(|| {
                map.values()
                    .find_map(|v| v.as_str().map(str::to_string))
            })
        }
        _ => None,
    }
}

/// 市场条目默认版本的安装参数：(spec, registry)。
fn market_install_target(entry: &Value) -> Option<(String, Option<String>)> {
    let default_version = entry
        .get("defaultVersion")
        .and_then(|v| v.as_str())
        .map(str::to_string);
    let versions = entry.get("versions")?.as_array()?;
    let chosen = versions
        .iter()
        .find(|version| {
            default_version
                .as_deref()
                .is_some_and(|dv| version.get("version").and_then(|v| v.as_str()) == Some(dv))
        })
        .or_else(|| versions.first())?;
    let install = chosen.get("install")?;
    let spec = install.get("spec")?.as_str()?.to_string();
    let registry = install
        .get("registry")
        .and_then(|v| v.as_str())
        .map(str::to_string);
    Some((spec, registry))
}

/// `@deepseek-ai/dsh-plugin-manager/tools` → `Plugin Manager / Tools`。
fn plugin_display_name(module: &str) -> String {
    let mut name = module.trim();
    if let Some(rest) = name.strip_prefix("@deepseek-ai/") {
        name = rest;
    }
    let name = name.strip_prefix("dsh-").unwrap_or(name);
    let mut out = String::new();
    for (index, part) in name.split(['-', '/', '_']).filter(|p| !p.is_empty()).enumerate() {
        if index > 0 {
            out.push_str(" / ");
        }
        let mut chars = part.chars();
        if let Some(first) = chars.next() {
            out.extend(first.to_uppercase());
            out.push_str(chars.as_str());
        }
    }
    if out.is_empty() {
        module.to_string()
    } else {
        out
    }
}

/// 头像底色（按 id 取一个稳定的颜色）。
fn provider_accent(id: &str) -> u32 {
    const PALETTE: [u32; 6] = [0x2f6fb5, 0x3f7a55, 0x8a5a2b, 0x6b4c8a, 0x2b7a7a, 0x8a4b4b];
    let sum: usize = id.bytes().map(|b| b as usize).sum();
    PALETTE[sum % PALETTE.len()]
}

